import { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';

const STORAGE_KEY = 'volley_hub_filters';

const getStorageKey = (userId) => {
    return userId ? `${STORAGE_KEY}_user_${userId}` : STORAGE_KEY;
};

export const useFilters = (initialFilters = {}) => {
    const { user } = useAuth();
    const [filters, setFilters] = useState(initialFilters);
    const [showFilters, setShowFilters] = useState(false);

    // Загрузка фильтров из localStorage при монтировании или смене пользователя
    useEffect(() => {
        const storageKey = getStorageKey(user?.id);
        const savedFilters = localStorage.getItem(storageKey);
        if (savedFilters) {
            try {
                const parsed = JSON.parse(savedFilters);
                setFilters(parsed);
            } catch (e) {
                console.error('Error loading filters:', e);
            }
        } else if (user?.id) {
            // Для нового пользователя сбрасываем фильтры
            setFilters({});
        }
    }, [user?.id]);

    // Сохранение фильтров в localStorage при изменении (только для авторизованных)
    useEffect(() => {
        const storageKey = getStorageKey(user?.id);
        if (user?.id && Object.keys(filters).length > 0) {
            localStorage.setItem(storageKey, JSON.stringify(filters));
        } else if (user?.id && Object.keys(filters).length === 0) {
            // Если фильтры пустые, удаляем из localStorage
            localStorage.removeItem(storageKey);
        }
    }, [filters, user?.id]);

    const updateFilter = useCallback((key, value) => {
        setFilters(prev => ({ ...prev, [key]: value }));
    }, []);

    const resetFilters = useCallback(() => {
        setFilters({});
        const storageKey = getStorageKey(user?.id);
        if (user?.id) {
            localStorage.removeItem(storageKey);
        }
    }, [user?.id]);

    const applyFilters = useCallback((newFilters) => {
        setFilters(newFilters);
        setShowFilters(false);
    }, []);

    return {
        filters,
        showFilters,
        setShowFilters,
        updateFilter,
        resetFilters,
        applyFilters
    };
};
